INSERT INTO record_revision (record_id, revision, document, changed_at, changed_by, change_summary) VALUES ('ADR-0008', 1, '{"alternatives":"Direct per-kind string templates with a separate Markdown parser; a Markdown AST with no Strata-owned IR; or one-way rendering now and parser design later. These approaches either make the two directions drift-prone or couple domain behavior directly to a format-specific representation.","consequences":"The renderer, parser, and template scaffold share one intermediate contract and can be tested for round-trip stability. The IR adds types and a conversion layer before Markdown output, but that cost is justified by two consumers and makes future Pandoc or JSON projections possible without changing domain semantics.","context":"Specification section 18 sketches an Engineering Document IR with Heading, Paragraph, List, CodeBlock, Table, Diagram, RecordReference, and EvidenceReference blocks, but marks an internal Rust IR as a SHOULD. Phase 2a now has two consumers: rendering structured records out to Markdown and parsing Markdown back into structured records for future --file or stdin input. Direct string templating is easy for one direction but gives the parser no stable structure to target.","decision":"We will use one shared, typed Engineering Document IR for both directions. Rendering maps a validated JSON document to per-kind IR blocks and then to Pandoc-compatible Markdown; parsing maps the Markdown into the same IR and then applies the same per-kind section rules to produce JSON. The IR will include the specification''s block families—Heading, Paragraph, List, CodeBlock, Table, Diagram, RecordReference, and EvidenceReference—and will keep domain validation and SQLite behavior outside the presentation layer.","evidence":"docs/specification.md section 18 requires an engineering document-oriented intermediate representation and names the block families. Sections 19 and 22 require deterministic Pandoc-compatible Markdown while keeping engineering semantics independent of Pandoc. Issue #6 adds Markdown input and templates as consumers of the same mapping."}', '2026-08-19T08:18:48.941326317+00:00', NULL, 'created');
INSERT INTO record_revision (record_id, revision, document, changed_at, changed_by, change_summary) VALUES ('ADR-0008', 2, '{"alternatives":"Direct per-kind string templates with a separate Markdown parser; a Markdown AST with no Strata-owned IR; or one-way rendering now and parser design later. These approaches either make the two directions drift-prone or couple domain behavior directly to a format-specific representation.","consequences":"The renderer, parser, and template scaffold share one intermediate contract and can be tested for round-trip stability. The IR adds types and a conversion layer before Markdown output, but that cost is justified by two consumers and makes future Pandoc or JSON projections possible without changing domain semantics.","context":"Specification section 18 sketches an Engineering Document IR with Heading, Paragraph, List, CodeBlock, Table, Diagram, RecordReference, and EvidenceReference blocks, but marks an internal Rust IR as a SHOULD. Phase 2a now has two consumers: rendering structured records out to Markdown and parsing Markdown back into structured records for future --file or stdin input. Direct string templating is easy for one direction but gives the parser no stable structure to target.","decision":"We will use one shared, typed Engineering Document IR for both directions. Rendering maps a validated JSON document to per-kind IR blocks and then to Pandoc-compatible Markdown; parsing maps the Markdown into the same IR and then applies the same per-kind section rules to produce JSON. The IR will include the specification''s block families—Heading, Paragraph, List, CodeBlock, Table, Diagram, RecordReference, and EvidenceReference—and will keep domain validation and SQLite behavior outside the presentation layer.","evidence":"docs/specification.md section 18 requires an engineering document-oriented intermediate representation and names the block families. Sections 19 and 22 require deterministic Pandoc-compatible Markdown while keeping engineering semantics independent of Pandoc. Issue #6 adds Markdown input and templates as consumers of the same mapping."}', '2026-08-19T13:37:55.387309192+00:00', NULL, 'status changed to accepted');
INSERT INTO record_revision (record_id, revision, document, changed_at, changed_by, change_summary) VALUES ('ADR-0009', 1, '{"alternatives":"Give RFC/PDR/ADR/EDR separate frontmatter schemas; preserve arbitrary top-level relationship keys; or copy the specification example exactly with identifier instead of the repository''s established id field. Separate schemas increase parser branching, while arbitrary keys make validation and round trips ambiguous. The common contract keeps the repository''s id convention and adds the explicit projection metadata needed for deterministic output.","consequences":"Every kind has the same metadata validation and parser surface, and a rendered file declares enough identity and projection information to be checked independently. The renderer must serialize empty tags and relationships deterministically, and the parser must reject unknown or incorrectly typed frontmatter fields rather than silently discard them.","context":"The specification section 19 gives an ADR-shaped YAML example with title, identifier, record-type, status, revision, date, tags, and relationships. The existing hand-written records use a smaller frontmatter vocabulary and vary in optional relationship fields. Rendering and parsing need one explicit contract rather than kind-specific guesses.","decision":"We will use one frontmatter shape for RFC, PDR, ADR, and EDR. The fields are id (for example RFC-0001), title, record-type (rfc, pdr, adr, or edr), status, revision (integer), date (ISO calendar date), slug, tags (a sequence, possibly empty), and relationships (a mapping from relation name to a sequence of record IDs, possibly empty). No frontmatter field is kind-specific; kind-specific content remains in the ordered body sections. Existing derived-from and constrained-by facts are represented as entries in relationships rather than as ad hoc top-level keys.","evidence":"docs/specification.md sections 19 and 23 identify title, identifier, record type, status, revision, date, tags, and relationships as publication metadata. Existing records establish id, title, status, date, and derived-from conventions; this decision normalizes those relationship facts under one relationships mapping."}', '2026-08-19T08:18:49.009451992+00:00', NULL, 'created');
INSERT INTO record_revision (record_id, revision, document, changed_at, changed_by, change_summary) VALUES ('ADR-0009', 2, '{"alternatives":"Give RFC/PDR/ADR/EDR separate frontmatter schemas; preserve arbitrary top-level relationship keys; copy the specification example exactly with identifier instead of the repository''s established id field; or show both outgoing and incoming relationships in frontmatter. Separate schemas increase parser branching, and arbitrary keys make validation and round trips ambiguous. Showing incoming relationships was considered and rejected for this decision specifically because it requires an inverse-relation vocabulary that does not exist yet for most of the ten defined relations -- building that now would be speculative, not motivated by an actual need.","consequences":"Every kind has the same metadata validation and parser surface, and a rendered file declares enough identity and projection information to be checked independently. The renderer must serialize empty tags and relationships deterministically, and the parser must reject unknown or incorrectly typed frontmatter fields rather than silently discard them. A record''s own file does not show what produced it or what points at it -- an ADR''s frontmatter will not list its originating PDR. That information is one strata graph call away and is not duplicated into every downstream file''s frontmatter.","context":"The specification section 19 gives an ADR-shaped YAML example with title, identifier, record-type, status, revision, date, tags, and relationships. The existing hand-written records use a smaller frontmatter vocabulary and vary in optional relationship fields. Rendering and parsing need one explicit contract rather than kind-specific guesses.","decision":"We will use one frontmatter shape for RFC, PDR, ADR, and EDR. The fields are id (for example RFC-0001), title, record-type (rfc, pdr, adr, or edr), status, revision (integer), date (ISO calendar date), slug, tags (a sequence, possibly empty), and relationships (a mapping from relation name to a sequence of record IDs, possibly empty). No frontmatter field is kind-specific; kind-specific content remains in the ordered body sections. relationships reflects outgoing edges only -- relations where this record is the source, exactly as stored in record_relation. It does not include incoming edges. The existing relation vocabulary (relates-to, derived-from, explored-by, produces, resolves, constrains, implements, implemented-by, supported-by, supersedes) declares an explicit inverse pair for only one relation (implements / implemented-by); inventing inverse names for the rest so incoming edges could be shown too is deliberately out of scope here, deferred until a real need for it appears. strata graph <id> remains the way to discover what points at a record, not its own frontmatter.","evidence":"docs/specification.md sections 19 and 23 identify title, identifier, record type, status, revision, date, tags, and relationships as publication metadata. Existing records establish id, title, status, date, and derived-from conventions; this decision normalizes those relationship facts under one relationships mapping, scoped to outgoing edges only. records/src/validation.rs''s RELATIONSHIPS constant is the authoritative relation vocabulary and shows only one declared inverse pair."}', '2026-08-19T13:37:46.001864060+00:00', NULL, 'scope relationships frontmatter field to outgoing edges only');
INSERT INTO record_revision (record_id, revision, document, changed_at, changed_by, change_summary) VALUES ('ADR-0009', 3, '{"alternatives":"Give RFC/PDR/ADR/EDR separate frontmatter schemas; preserve arbitrary top-level relationship keys; copy the specification example exactly with identifier instead of the repository''s established id field; or show both outgoing and incoming relationships in frontmatter. Separate schemas increase parser branching, and arbitrary keys make validation and round trips ambiguous. Showing incoming relationships was considered and rejected for this decision specifically because it requires an inverse-relation vocabulary that does not exist yet for most of the ten defined relations -- building that now would be speculative, not motivated by an actual need.","consequences":"Every kind has the same metadata validation and parser surface, and a rendered file declares enough identity and projection information to be checked independently. The renderer must serialize empty tags and relationships deterministically, and the parser must reject unknown or incorrectly typed frontmatter fields rather than silently discard them. A record''s own file does not show what produced it or what points at it -- an ADR''s frontmatter will not list its originating PDR. That information is one strata graph call away and is not duplicated into every downstream file''s frontmatter.","context":"The specification section 19 gives an ADR-shaped YAML example with title, identifier, record-type, status, revision, date, tags, and relationships. The existing hand-written records use a smaller frontmatter vocabulary and vary in optional relationship fields. Rendering and parsing need one explicit contract rather than kind-specific guesses.","decision":"We will use one frontmatter shape for RFC, PDR, ADR, and EDR. The fields are id (for example RFC-0001), title, record-type (rfc, pdr, adr, or edr), status, revision (integer), date (ISO calendar date), slug, tags (a sequence, possibly empty), and relationships (a mapping from relation name to a sequence of record IDs, possibly empty). No frontmatter field is kind-specific; kind-specific content remains in the ordered body sections. relationships reflects outgoing edges only -- relations where this record is the source, exactly as stored in record_relation. It does not include incoming edges. The existing relation vocabulary (relates-to, derived-from, explored-by, produces, resolves, constrains, implements, implemented-by, supported-by, supersedes) declares an explicit inverse pair for only one relation (implements / implemented-by); inventing inverse names for the rest so incoming edges could be shown too is deliberately out of scope here, deferred until a real need for it appears. strata graph <id> remains the way to discover what points at a record, not its own frontmatter.","evidence":"docs/specification.md sections 19 and 23 identify title, identifier, record type, status, revision, date, tags, and relationships as publication metadata. Existing records establish id, title, status, date, and derived-from conventions; this decision normalizes those relationship facts under one relationships mapping, scoped to outgoing edges only. records/src/validation.rs''s RELATIONSHIPS constant is the authoritative relation vocabulary and shows only one declared inverse pair."}', '2026-08-19T13:37:55.447832404+00:00', NULL, 'status changed to accepted');
INSERT INTO record_revision (record_id, revision, document, changed_at, changed_by, change_summary) VALUES ('ADR-0010', 1, '{"alternatives":"Normalize line endings and trailing whitespace before comparison; parse both files into ASTs; or compare only semantic JSON/frontmatter values. Those approaches can accept changes to the human-readable projection and weaken the review and reproducibility guarantee. Byte equality makes deterministic rendering an enforceable contract.","consequences":"Export output must choose and consistently emit its line endings, whitespace, ordering, and final newline. Developers on platforms with different default line endings cannot rely on local normalization; the generated file must be committed exactly as the renderer emits it.","context":"ADR-0003 makes Markdown a deterministic projection and docs/specification.md section 28 calls for CI verification of committed projections. The check must define whether formatting normalization can hide drift.","decision":"strata export --check will render the canonical record to the exact expected path and compare the resulting byte sequence directly with the committed file. It will not normalize trailing whitespace, line endings, Unicode normalization, YAML key order, or final-newline presence. A missing file, extra stale file, or any byte difference is a failure.","evidence":"docs/specification.md section 19 requires deterministic rendering and section 28 says export --check should fail when committed projections differ. ADR-0003 requires byte-identical Markdown for identical canonical state."}', '2026-08-19T08:18:49.195140527+00:00', NULL, 'created');
INSERT INTO record_revision (record_id, revision, document, changed_at, changed_by, change_summary) VALUES ('ADR-0010', 2, '{"alternatives":"Normalize line endings and trailing whitespace before comparison; parse both files into ASTs; or compare only semantic JSON/frontmatter values. Those approaches can accept changes to the human-readable projection and weaken the review and reproducibility guarantee. Byte equality makes deterministic rendering an enforceable contract.","consequences":"Export output must choose and consistently emit its line endings, whitespace, ordering, and final newline. Developers on platforms with different default line endings cannot rely on local normalization; the generated file must be committed exactly as the renderer emits it.","context":"ADR-0003 makes Markdown a deterministic projection and docs/specification.md section 28 calls for CI verification of committed projections. The check must define whether formatting normalization can hide drift.","decision":"strata export --check will render the canonical record to the exact expected path and compare the resulting byte sequence directly with the committed file. It will not normalize trailing whitespace, line endings, Unicode normalization, YAML key order, or final-newline presence. A missing file, extra stale file, or any byte difference is a failure.","evidence":"docs/specification.md section 19 requires deterministic rendering and section 28 says export --check should fail when committed projections differ. ADR-0003 requires byte-identical Markdown for identical canonical state."}', '2026-08-19T13:37:55.515226419+00:00', NULL, 'status changed to accepted');
INSERT INTO record_revision (record_id, revision, document, changed_at, changed_by, change_summary) VALUES ('ADR-0011', 1, '{"alternatives":"Accept missing fields as empty strings, infer missing headings from nearby prose, ignore unknown frontmatter, or parse best effort and rely on later validation. Those options violate the explicit-failure rule and can turn a human-readable but structurally invalid document into misleading canonical state.","consequences":"Templates and hand-authored input must include the complete frontmatter and exact ordered required sections. Errors are actionable at the input boundary, and failed parsing leaves the database unchanged because the CLI validates before mutation.","context":"Future strata new and strata revise Markdown input will be a mutation path and therefore part of the CLI trust boundary. A malformed document must not become a default or partially populated JSON document.","decision":"Markdown input is malformed when the opening and closing YAML frontmatter delimiters are not the first and matching delimiter lines, the YAML cannot be parsed, a required metadata field is missing or has the wrong scalar/sequence/mapping type, the declared id or record-type is invalid, a required mapped section heading is absent, duplicated, at the wrong level, or out of the prescribed order, or section boundaries are ambiguous. The CLI will return a nonzero explicit error naming the file, record kind, and missing or malformed field/section; it will not create or revise a record.","evidence":"AGENTS.md rule 7 requires validation and decode failures to remain explicit errors. PDR-0001 requires bad requests to fail without partial mutation, and ADR-0002 makes the CLI the sole validated mutation boundary. Issue #6 specifically requires clear errors for missing sections and broken frontmatter."}', '2026-08-19T08:18:49.233640586+00:00', NULL, 'created');
INSERT INTO record_revision (record_id, revision, document, changed_at, changed_by, change_summary) VALUES ('ADR-0011', 2, '{"alternatives":"Accept missing fields as empty strings, infer missing headings from nearby prose, ignore unknown frontmatter, or parse best effort and rely on later validation. Those options violate the explicit-failure rule and can turn a human-readable but structurally invalid document into misleading canonical state.","consequences":"Templates and hand-authored input must include the complete frontmatter and exact ordered required sections. Errors are actionable at the input boundary, and failed parsing leaves the database unchanged because the CLI validates before mutation.","context":"Future strata new and strata revise Markdown input will be a mutation path and therefore part of the CLI trust boundary. A malformed document must not become a default or partially populated JSON document.","decision":"Markdown input is malformed when the opening and closing YAML frontmatter delimiters are not the first and matching delimiter lines, the YAML cannot be parsed, a required metadata field is missing or has the wrong scalar/sequence/mapping type, the declared id or record-type is invalid, a required mapped section heading is absent, duplicated, at the wrong level, or out of the prescribed order, or section boundaries are ambiguous. The CLI will return a nonzero explicit error naming the file, record kind, and missing or malformed field/section; it will not create or revise a record.","evidence":"AGENTS.md rule 7 requires validation and decode failures to remain explicit errors. PDR-0001 requires bad requests to fail without partial mutation, and ADR-0002 makes the CLI the sole validated mutation boundary. Issue #6 specifically requires clear errors for missing sections and broken frontmatter."}', '2026-08-19T13:37:55.577974884+00:00', NULL, 'status changed to accepted');
INSERT INTO record_revision (record_id, revision, document, changed_at, changed_by, change_summary) VALUES ('ADR-0012', 1, '{"alternatives":"Recompute the slug on every title change and delete or rename the stale old file; preserve the old file as an alias; or require manual filename repair. Recomputing makes a metadata edit a path migration and creates stale-file and link-management failure modes, while aliases and manual repair add competing projections.","consequences":"Paths are stable for cross-references, code review history, and external links. A slug can become semantically stale relative to a renamed title, but that is an intentional stable-identity tradeoff; future tooling may display the current title in metadata without changing the path.","context":"Issue #11 will allow a record title to change after creation. If the filename is derived from the current title, a title update becomes a file move and can leave a stale old projection or break links and reviews.","decision":"The filename slug is allocated and persisted at record creation and remains fixed for the record''s lifetime, even when title changes. Rendering and export continue to use the stored creation slug; title updates change frontmatter and the document heading but never rename the path. The canonical record must retain this immutable slug alongside its identity so export does not need to infer history from the filesystem.","evidence":"Issue #6 asks for the title-renaming choice in light of issue #11. Issue #11 is concerned with title updates, while ADR-0003 and docs/specification.md section 28 make committed projections and their paths operationally significant. EDR-0003 supplies the deterministic creation-time slug algorithm."}', '2026-08-19T08:18:49.282734500+00:00', NULL, 'created');
INSERT INTO record_revision (record_id, revision, document, changed_at, changed_by, change_summary) VALUES ('ADR-0012', 2, '{"alternatives":"Recompute the slug on every title change and delete or rename the stale old file; preserve the old file as an alias; or require manual filename repair. Recomputing makes a metadata edit a path migration and creates stale-file and link-management failure modes, while aliases and manual repair add competing projections.","consequences":"Paths are stable for cross-references, code review history, and external links. A slug can become semantically stale relative to a renamed title, but that is an intentional stable-identity tradeoff; future tooling may display the current title in metadata without changing the path.","context":"Issue #11 will allow a record title to change after creation. If the filename is derived from the current title, a title update becomes a file move and can leave a stale old projection or break links and reviews.","decision":"The filename slug is allocated and persisted at record creation and remains fixed for the record''s lifetime, even when title changes. Rendering and export continue to use the stored creation slug; title updates change frontmatter and the document heading but never rename the path. The canonical record must retain this immutable slug alongside its identity so export does not need to infer history from the filesystem.","evidence":"Issue #6 asks for the title-renaming choice in light of issue #11. Issue #11 is concerned with title updates, while ADR-0003 and docs/specification.md section 28 make committed projections and their paths operationally significant. EDR-0003 supplies the deterministic creation-time slug algorithm."}', '2026-08-19T13:37:55.640943835+00:00', NULL, 'status changed to accepted');
INSERT INTO record_revision (record_id, revision, document, changed_at, changed_by, change_summary) VALUES ('ADR-0013', 1, '{"alternatives":"Teach the existing Markdown importer to replay frontmatter status, revision history, and relationships in addition to body content -- rejected as insufficient even if built: evidence and code references have no representation in the Markdown contract at all (ADR-0008, ADR-0009 scoped frontmatter and section mapping to record content and relationships only), so this path could never be a complete backup regardless of how much importer logic were added, only a partial one that silently drops two entire tables. Shell out to the system `sqlite3` binary''s `.dump` command -- rejected: adds a dependency on a tool being present on the host outside Strata''s own control, which cuts against the CLI being self-contained and self-describing (spec section 14); a native implementation keeps `strata dump`/`strata restore` working anywhere the `strata` binary itself works. Rely on `.strata/self-host.db` staying gitignored with no git-backed recovery path at all, treating out-of-band backup (disk snapshots, litestream, manual copies) as sufficient -- rejected: this project''s own founding motivation (RFC-0001) is preventing silent, unrecoverable loss of engineering knowledge; leaving the only copy of canonical state with no git history at all is the same category of risk the Markdown projection was partly meant to mitigate (spec section 28), just left unresolved for the parts Markdown cannot cover. Git LFS to track the binary `.strata/self-host.db` file directly -- rejected: SQLite is a binary format Git cannot meaningfully diff or three-way-merge, so two branches independently mutating canonical state would produce an unresolvable binary conflict rather than a mergeable text conflict; a plain-text SQL dump gets normal `git diff`/merge behavior on the actual row-level changes instead.","consequences":"A new `strata dump` command performs a full native reimplementation of SQL row serialization (escaping, NULL handling, one `INSERT` per row) for five tables -- this is new surface area analogous in size to the Markdown renderer (ADR-0008), not a small addition, and its exact serialization rules are implementation detail this ADR does not fix (parallel to how ADR-0008 handed detailed section-mapping rules to EDR-0004; a follow-on EDR may be warranted once implementation specifics are settled). `strata restore` becomes the first command that reconstructs a complete database rather than one record, and needs its own transactional-integrity guarantee (ADR-0001''s single-writer model, and the rollback guarantee store/src/mutations.rs''s revise() already demonstrates, both apply directly). The committed dump file is checked into git alongside `docs/records/`, at a location this ADR does not fix (a follow-on decision or the implementing EDR should place it, e.g. outside `docs/records/` so it is not mistaken for a per-record Markdown file). `strata dump --check` joins `strata export --check` as a second CI-verifiable consistency gate. Markdown''s scope and purpose are unchanged by this decision.","context":"ADR-0003 established that Markdown is a generated, read-only projection of canonical SQLite state, useful for human review and repository browsing (spec sections 18-19). It was never designed or claimed to be a full-fidelity backup path, and a concrete test confirms it is not one in practice: recreating ADR-0001 from its own checked-in Markdown file via `strata new adr ... --file docs/records/adr/0001-....md` reproduces the document body correctly but returns `status: proposed, revision: 1` where the real record is `status: accepted, revision: 2`. Tracing why, in cli/src/parse/frontmatter.rs and cli/src/parse.rs: the frontmatter parser fully parses and validates `status`, `revision`, and `relationships`, but document_to_json() (cli/src/parse.rs) only ever reads the body sections into the created document -- the parsed status, revision, and relationships are validated for well-formedness and then discarded, never applied via store::set_status or store::link. There is no bulk import/restore command at all; `new --file` and `revise --file` are the only Markdown-input paths, and neither reconstructs more than one record''s current content. Evidence and code references (store/src/evidence.rs, store/src/code_reference.rs) are entirely absent from the Markdown contract (ADR-0008, ADR-0009) and would not round-trip through Markdown even if the above gap were closed.\n\nThe `.strata/self-host.db` file itself is gitignored and untracked (commit ef91691), so today canonical state exists in exactly one place with no git-backed recovery path at all if that file is lost or corrupted.\n\nClosing this gap by teaching the Markdown importer to also replay status, revision history, and relationships from frontmatter was considered and rejected as the approach -- see Alternatives.","decision":"We will add a second, separate git-trackable projection whose sole purpose is full-fidelity backup and restore, generated as plain-text SQL: a native Rust dump (no dependency on the external `sqlite3` binary, keeping the CLI self-contained per spec section 14) that reads `sqlite_master` for schema DDL and each of Strata''s own domain tables -- `engineering_record`, `record_relation`, `record_revision`, `evidence`, `code_reference`, in that order to respect foreign-key dependencies -- and emits `INSERT` statements reproducing every row exactly. `engineering_record_fts` is excluded from the dump: its content (title, body, tags) is fully derived from `engineering_record` by store::index_record, so it is rebuilt on restore rather than dumped as redundant data. Refinery''s own migration-history table is likewise excluded; a restore target gets its schema and migration history from a normal `Store::open()` migration run, not from replayed rows.\n\nThis is a projection with a different purpose than Markdown, not a replacement for it: Markdown remains the human-review artifact (ADR-0003 stands unchanged), while the SQL dump exists specifically so a corrupted or lost `.strata/self-host.db` can be reconstructed byte-for-byte-equivalent in content from git history alone. Like `strata export`, dump generation is an explicit, deliberate step (`strata dump`), not automatic on every mutation, and gets the same CI-verifiable consistency guarantee ADR-0010 gave Markdown: `strata dump --check` fails if the committed file no longer matches canonical state.","evidence":"cli/src/parse.rs''s document_to_json() and cli/src/parse/frontmatter.rs: the traced code path confirming frontmatter status/revision/relationships are validated but discarded, the concrete gap motivating this decision. A reproduction: recreating ADR-0001 from docs/records/adr/0001-sqlite-as-strata-s-canonical-persistent-store.md via `strata new adr ... --file` into a fresh scratch database returned `status: proposed, revision: 1` against the real record''s `status: accepted, revision: 2`. ADR-0001, ADR-0003: the prior decisions this one extends (SQLite as canonical store; Markdown as a non-canonical, review-purposed projection) without revising either. ADR-0010: the `export --check` precedent this decision''s `dump --check` mirrors. commit ef91691: the decision to gitignore `.strata/self-host.db`, which is what leaves canonical state with no git-backed recovery path today."}', '2026-08-19T19:18:58.823709977+00:00', NULL, 'created');
INSERT INTO record_revision (record_id, revision, document, changed_at, changed_by, change_summary) VALUES ('ADR-0013', 2, '{"alternatives":"Teach the existing Markdown importer to replay frontmatter status, revision history, and relationships in addition to body content -- rejected as insufficient even if built: evidence and code references have no representation in the Markdown contract at all (ADR-0008, ADR-0009 scoped frontmatter and section mapping to record content and relationships only), so this path could never be a complete backup regardless of how much importer logic were added, only a partial one that silently drops two entire tables. Shell out to the system `sqlite3` binary''s `.dump` command -- rejected: adds a dependency on a tool being present on the host outside Strata''s own control, which cuts against the CLI being self-contained and self-describing (spec section 14); a native implementation keeps `strata dump`/`strata restore` working anywhere the `strata` binary itself works. Rely on `.strata/self-host.db` staying gitignored with no git-backed recovery path at all, treating out-of-band backup (disk snapshots, litestream, manual copies) as sufficient -- rejected: this project''s own founding motivation (RFC-0001) is preventing silent, unrecoverable loss of engineering knowledge; leaving the only copy of canonical state with no git history at all is the same category of risk the Markdown projection was partly meant to mitigate (spec section 28), just left unresolved for the parts Markdown cannot cover. Git LFS to track the binary `.strata/self-host.db` file directly -- rejected: SQLite is a binary format Git cannot meaningfully diff or three-way-merge, so two branches independently mutating canonical state would produce an unresolvable binary conflict rather than a mergeable text conflict; a plain-text SQL dump gets normal `git diff`/merge behavior on the actual row-level changes instead.","consequences":"A new `strata dump` command performs a ful